scripts.build:
node build.js && node mobile-fixes.js && node -e "const fs=require('fs');const p='public/index.html';let h=fs.readFileSync(p,'utf8');if(!h.includes('mobile-pricing-affordance-v1')){h=h.replace('</style>','    /* mobile-pricing-affordance-v1 */
    @media (max-width: 680px) {
      .plan-tab summary { grid-template-columns: 1fr auto; gap: 8px 12px; }
      .plan-tab summary::after { content: "See all options"; grid-column: 1 / -1; min-height: 38px; display: inline-flex; align-items: center; justify-content: center; margin-top: 4px; border: 1px solid var(--line-strong); border-radius: var(--radius); color: var(--text); background: rgba(255,255,255,.055); font-family: "Barlow Condensed", sans-serif; font-size: 14px; font-weight: 800; letter-spacing: .12em; line-height: 1; text-transform: uppercase; }
      .plan-tab[open] summary::after { content: "Hide options"; border-color: rgba(212, 214, 79, .48); color: #111318; background: var(--lime); }
      .plan-tab span { color: rgba(244, 242, 236, .9); font-size: 13px; font-weight: 650; }
      .plan-tab small { color: rgba(244, 242, 236, .74); font-size: 13px; line-height: 1.35; }
    }
  </style>')}if(!h.includes('mobile-pricing-choice-v2')){h=h.replaceAll('Best value · 24 mo','Pro Performance · 24 mo').replaceAll('Buy Best Value','Choose 24 Months').replaceAll('<span class="tag">Best value</span>','<span class="tag">Pro performance</span>');h=h.replace('</style>','    /* mobile-pricing-choice-v2 */
    @media (max-width: 680px) {
      .plan-tab[open] summary::after { border-color: rgba(102, 183, 214, .42); color: var(--text); background: rgba(102, 183, 214, .16); }
      .option-row:nth-child(1) .btn { border-color: rgba(244, 242, 236, .36); background: rgba(244, 242, 236, .075); color: var(--text); }
      .option-row:nth-child(2) .btn { border-color: rgba(102, 183, 214, .5); background: rgba(102, 183, 214, .18); color: var(--text); }
      .option-row:nth-child(3) .btn { border-color: transparent; background: var(--lime); color: #111318; }
    }
  </style>')}fs.writeFileSync(p,h)"
